func SnapshotKVCache(c *KVCache) *Snapshot {
	c.mu.RLock()
	defer c.mu.RUnlock()
	snap := &Snapshot{Entries: make(map[string]string, len(c.data))}
	for k, e := range c.data {
		if !e.expiresAt.IsZero() {
			continue // skip TTL'd entries
		}
		snap.Entries[k] = e.value
	}
	return snap
}

